static void smartmicrowavesystem_eventqueue_init(smartmicrowavesystem_eventqueue * eq, smartmicrowavesystem_event *buffer, sc_integer capacity)
{
	eq->events = buffer;
	eq->capacity = capacity;
	eq->push_index = 0;
	eq->pop_index = 0;
	eq->size = 0;
}

static sc_integer smartmicrowavesystem_eventqueue_size(smartmicrowavesystem_eventqueue * eq)
{
	return eq->size;
}

static smartmicrowavesystem_event smartmicrowavesystem_eventqueue_pop(smartmicrowavesystem_eventqueue * eq)
{
	smartmicrowavesystem_event event;
	if(smartmicrowavesystem_eventqueue_size(eq) <= 0) {
		smartmicrowavesystem_event_init(&event, SmartMicrowaveSystem_invalid_event);
	}
	else {
		event = eq->events[eq->pop_index];
		
		if(eq->pop_index < eq->capacity - 1) {
			eq->pop_index++;
		} 
		else {
			eq->pop_index = 0;
		}
		eq->size--;
	}
	return event;
}
static sc_boolean smartmicrowavesystem_eventqueue_push(smartmicrowavesystem_eventqueue * eq, smartmicrowavesystem_event ev)
{
	if(smartmicrowavesystem_eventqueue_size(eq) == eq->capacity) {
		return bool_false;
	}
	else {
		eq->events[eq->push_index] = ev;
		
		if(eq->push_index < eq->capacity - 1) {
			eq->push_index++;
		}
		else {
			eq->push_index = 0;
		}
		eq->size++;
		
		return bool_true;
	}
}
static void smartmicrowavesystem_event_init(smartmicrowavesystem_event * ev, SmartMicrowaveSystemEventID name)
{
	ev->name = name;
}

static void smartMicrowaveSystem_add_event_to_queue(smartmicrowavesystem_eventqueue * eq, SmartMicrowaveSystemEventID name)
{
	smartmicrowavesystem_event event;
	smartmicrowavesystem_event_init(&event, name);
	smartmicrowavesystem_eventqueue_push(eq, event);
}

